mapper.select:
SELECT target_id, MAX(event_time) AS read_at
FROM t_system_audit_log
WHERE operation = 'IN_APP_NOTIFICATION_READ'
  AND target_type = #{type}
  AND user_id = #{user}
  AND target_id IN
  #{id}
GROUP BY target_id

mapper.insert:
INSERT IGNORE INTO t_system_audit_log(
    user_id, operation, audit_class, outcome, target_type, target_id,
    operation_detail, detail_schema_version, event_time, idempotency_key
) VALUES(
    #{user}, 'IN_APP_NOTIFICATION_READ', 'BUSINESS', 'SUCCESS', #{type}, #{target},
    JSON_OBJECT('readAt', NOW(3)), 'in-app-read-v1', NOW(3), #{key}
)
